      updateBundleTime: function updateBundleTime() {
        var now = new Date(Global.networkTimer);
        var tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        tomorrow.setHours(0, 0, 0, 0);
        var millisecondsUntilTomorrow = tomorrow.getTime() - now;
        var currentDayOfWeek = now.getDay();
        var daysUntilNextMonday = (1 - currentDayOfWeek + 7) % 7 || 7;
        var nextMonday = new Date(now);
        nextMonday.setDate(now.getDate() + daysUntilNextMonday);
        nextMonday.setHours(0, 0, 0, 0);
        var millisecondsUntilNextMonday = nextMonday.getTime() - now.getTime();
        var nextDay = Global.utils.getRemainTime(millisecondsUntilTomorrow);
        var nextWeek = Global.utils.getRemainTime(millisecondsUntilNextMonday);
        this.dailyTimeLabel.getComponent("LabelUpdater").setString(nextDay.hours + Global.languageManager.t("hour") + " " + nextDay.minutes + Global.languageManager.t("minute"));
        nextWeek.days > 0 ? this.weeklyTimeLabel.getComponent("LabelUpdater").setString(nextWeek.days + Global.languageManager.t("day") + " " + nextWeek.hours + Global.languageManager.t("hour")) : this.weeklyTimeLabel.getComponent("LabelUpdater").setString(nextWeek.hours + Global.languageManager.t("hour") + " " + nextWeek.minutes + Global.languageManager.t("minute"));
      },
      updateDiamondShopTime: function updateDiamondShopTime() {
        var now = new Date(Global.networkTimer);
        var tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        tomorrow.setHours(0, 0, 0, 0);
        var millisecondsUntilTomorrow = tomorrow.getTime() - now;
        var nextDay = Global.utils.getRemainTime(millisecondsUntilTomorrow);
        this.diamondShopTimeLabel.getComponent("LabelUpdater").setString(nextDay.hours + Global.languageManager.t("hour") + " " + nextDay.minutes + Global.languageManager.t("minute"));
      },
